import {lazy, Suspense} from 'react'
import {Heading} from '@primer/react'
import {type Column, type DataTable as DataTableType, Table, Blankslate} from '@primer/react/experimental'
import {TrafficError} from './TrafficError'
import {LoadingState} from './TrafficLoading'
import type {ReactNode} from 'react'
import type {TrafficDataItem} from '../hooks/traffic-types'

const DataTable = lazy(async () => ({
  default: (await import('@primer/react/experimental')).DataTable,
})) as typeof DataTableType

interface TrafficDataTableProps {
  title: ReactNode
  data: TrafficDataItem[]
  isLoading: boolean
  error: string | null | undefined
  // Define a type for DataTable columns (customized to match Primer's DataTable expected structure)
  columns: Array<Column<TrafficDataItem>>
  emptyMessage: string
  ariaLabelledBy: string
  className?: string
}

export function TrafficDataTable({
  title,
  data,
  isLoading,
  error,
  columns,
  emptyMessage,
  ariaLabelledBy,
  className,
}: TrafficDataTableProps) {
  if (error) {
    return (
      <div className={className}>
        <Heading as="h2" className="f3 text-semibold mb-1 color-fg-default">
          {title}
        </Heading>
        <TrafficError error={error} />
      </div>
    )
  }

  return (
    <div className={className}>
      <Heading as="h2" id={ariaLabelledBy} className="f3 text-semibold mb-1 color-fg-default" data-hpc>
        {title}
      </Heading>

      <div className="tmp-mt-3">
        {isLoading ? (
          <LoadingState />
        ) : data && data.length > 0 ? (
          <Table.Container>
            <Suspense fallback={<LoadingState />}>
              <DataTable aria-labelledby={ariaLabelledBy} data={data} columns={columns} />
            </Suspense>
          </Table.Container>
        ) : (
          <Blankslate border>
            <Blankslate.Heading as="h3" className="mb-2 f4">
              {emptyMessage}
            </Blankslate.Heading>
            <Blankslate.Description className="f5">
              Data in this table may take several days to appear.
            </Blankslate.Description>
          </Blankslate>
        )}
      </div>
    </div>
  )
}
